import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { Html5Qrcode } from 'html5-qrcode';

// ── QR reader element ID (must be unique) ────
const QR_READER_ID = 'attendance-qr-reader';

export default function StudentDashboard() {
  const { user, logout, API } = useAuth();
  const navigate = useNavigate();
  const scannerRef = useRef(null);
  const [step, setStep] = useState('scan'); // scan | confirming | done
  const [scannedData, setScannedData] = useState(null);
  const [location, setLocation] = useState(null);
  const [geoStatus, setGeoStatus] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [cameraActive, setCameraActive] = useState(false);

  // ── Get user location on mount ────────────────
  useEffect(() => {
    if (!navigator.geolocation) {
      setError('Geolocation is not supported by your browser');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setGeoStatus('✅ Location acquired');
      },
      (err) => {
        setGeoStatus('❌ GPS access denied. Enable location services.');
        setError('GPS location is required to mark attendance');
        console.warn('GPS error:', err.message);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 30000 }
    );
  }, []);

  // ── Initialize QR scanner ─────────────────────
  const startScanner = useCallback(async () => {
    setError('');
    // Wait a tick for the QR reader div to be in the DOM
    await new Promise((r) => setTimeout(r, 100));

    try {
      // Clean up any previous instance
      if (scannerRef.current) {
        try { await scannerRef.current.stop(); } catch {}
        try { scannerRef.current.clear(); } catch {}
        scannerRef.current = null;
      }

      const scanner = new Html5Qrcode(QR_READER_ID);
      scannerRef.current = scanner;

      await scanner.start(
        { facingMode: 'environment' },
        {
          fps: 30,
          qrbox: { width: 250, height: 250 },
        },
        // onSuccess
        (decodedText) => {
          stopScanner();
          try {
            const data = JSON.parse(decodedText);
            setScannedData({
              sessionId: data.sid,
              subject: data.sub,
              expiresAt: data.exp,
            });
          } catch {
            setScannedData({ sessionId: decodedText.trim() });
          }
          setStep('confirming');
        },
        // onFailure — keep scanning
        () => {}
      );
      setCameraActive(true);
    } catch (err) {
      setError(
        'Camera access denied. Please allow camera permissions in your browser settings, or use the manual entry below.'
      );
      console.warn('Scanner error:', err);
    }
  }, []);

  // ── Stop scanner ──────────────────────────────
  const stopScanner = useCallback(() => {
    if (scannerRef.current) {
      try {
        scannerRef.current.stop().catch(() => {});
      } catch {}
      scannerRef.current = null;
      setCameraActive(false);
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (scannerRef.current) {
        try { scannerRef.current.stop().catch(() => {}); } catch {}
      }
    };
  }, []);

  // ── Manual session ID input ───────────────────
  const [manualSessionId, setManualSessionId] = useState('');

  const handleManualSubmit = (e) => {
    e.preventDefault();
    if (!manualSessionId.trim()) return;
    stopScanner();
    setScannedData({ sessionId: manualSessionId.trim() });
    setStep('confirming');
  };

  // ── Mark attendance ───────────────────────────
  const markAttendance = async () => {
    if (!location) {
      setError('GPS location not available');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await API.post('/attendance/mark', {
        sessionId: scannedData.sessionId,
        lat: location.lat,
        lng: location.lng,
      });
      setMessage(res.data.message);
      setStep('done');
    } catch (err) {
      // If role error, give a clearer message
      const msg = err.response?.data?.message || 'Failed to mark attendance';
      if (msg.includes('not authorized') || msg.includes('Role')) {
        setError(
          'Your account role is not "student". You need to register/login as a student to mark attendance. Use a different email to create a student account.'
        );
      } else {
        setError(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  // ── Reset ─────────────────────────────────────
  const resetScan = () => {
    setStep('scan');
    setScannedData(null);
    setMessage('');
    setError('');
    setManualSessionId('');
    stopScanner();
  };

  const handleLogout = () => {
    stopScanner();
    logout();
    navigate('/login');
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <div>
          <h1>🎓 Student Dashboard</h1>
          <span style={styles.roleBadge}>{user?.role}</span>
        </div>
        <div>
          <span style={styles.userInfo}>{user?.name}</span>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.content}>
        {/* ── GPS Status ── */}
        <div style={styles.card}>
          <h2 style={styles.cardTitle}>📍 Location Status</h2>
          <p style={{ color: location ? '#6c63ff' : '#ff6b6b' }}>
            {geoStatus || 'Acquiring GPS...'}
          </p>
          {location && (
            <p style={{ fontSize: '0.8rem', color: '#888' }}>
              {location.lat.toFixed(6)}, {location.lng.toFixed(6)}
            </p>
          )}
        </div>

        {/* ── Step 1: Scan QR ── */}
        {step === 'scan' && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>📷 Scan QR Code</h2>
            <p style={{ color: '#aaa', marginBottom: '12px' }}>
              Point your camera at the teacher's QR code
            </p>

            {/* QR scanner element — always rendered in DOM but hidden via CSS when not active */}
            <div id={QR_READER_ID} style={cameraActive ? styles.qrReader : styles.qrReaderHidden}></div>

            {!cameraActive && (
              <button onClick={startScanner} style={styles.button}>
                📸 Start Camera Scanner
              </button>
            )}

            {cameraActive && (
              <button
                onClick={() => { stopScanner(); }}
                style={{ ...styles.button, background: '#555', marginTop: '8px' }}
              >
                🛑 Stop Camera
              </button>
            )}

            <div style={styles.divider}>
              <span style={styles.dividerText}>OR enter code manually</span>
            </div>

            <form onSubmit={handleManualSubmit} style={styles.form}>
              <input
                value={manualSessionId}
                onChange={(e) => setManualSessionId(e.target.value)}
                placeholder="Paste session ID from QR"
                style={styles.input}
              />
              <button type="submit" style={{ ...styles.button, background: '#555' }}>
                Use Session ID
              </button>
            </form>
          </div>
        )}

        {/* ── Step 2: Confirm Attendance ── */}
        {step === 'confirming' && (
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>✅ Confirm Attendance</h2>
            {scannedData?.subject && (
              <p style={{ margin: '8px 0', fontSize: '1.1rem' }}>
                📚 <strong>{scannedData.subject}</strong>
              </p>
            )}
            <p style={{ fontSize: '0.85rem', color: '#aaa', wordBreak: 'break-all' }}>
              Session: {scannedData?.sessionId.slice(0, 24)}...
            </p>
            {location && (
              <p style={{ fontSize: '0.85rem', color: '#aaa', margin: '8px 0' }}>
                📍 GPS will be verified against classroom geo-fence
              </p>
            )}
            {error && <div style={styles.error}>{error}</div>}
            <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
              <button onClick={resetScan} style={{ ...styles.button, background: '#555', flex: 1 }}>
                Cancel
              </button>
              <button onClick={markAttendance} disabled={loading} style={{ ...styles.button, flex: 1 }}>
                {loading ? 'Marking...' : '✅ Mark Present'}
              </button>
            </div>
          </div>
        )}

        {/* ── Step 3: Success ── */}
        {step === 'done' && (
          <div style={styles.card}>
            <div style={{ textAlign: 'center', fontSize: '3rem', marginBottom: '12px' }}>🎉</div>
            <h2 style={{ ...styles.cardTitle, color: '#6c63ff', textAlign: 'center' }}>
              Attendance Marked!
            </h2>
            <p style={{ fontSize: '1.1rem', margin: '12px 0', textAlign: 'center' }}>{message}</p>
            <button onClick={resetScan} style={styles.button}>
              Scan Another QR
            </button>
          </div>
        )}

        {error && step === 'scan' && <div style={styles.error}>{error}</div>}
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', padding: '20px' },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px',
    flexWrap: 'wrap',
    gap: '10px',
  },
  roleBadge: {
    display: 'inline-block',
    background: '#6c63ff',
    color: '#fff',
    fontSize: '0.7rem',
    fontWeight: 'bold',
    padding: '3px 10px',
    borderRadius: '20px',
    textTransform: 'uppercase',
    letterSpacing: '1px',
    marginTop: '4px',
  },
  userInfo: { marginRight: '12px', color: '#a0a0c0' },
  logoutBtn: {
    padding: '8px 16px',
    borderRadius: '6px',
    border: '1px solid rgba(255,255,255,0.2)',
    background: 'transparent',
    color: '#ff6b6b',
    cursor: 'pointer',
  },
  content: { maxWidth: '500px', margin: '0 auto', display: 'flex', flexDirection: 'column', gap: '20px' },
  card: {
    background: 'rgba(255,255,255,0.06)',
    borderRadius: '12px',
    padding: '24px',
    backdropFilter: 'blur(10px)',
  },
  cardTitle: { marginBottom: '12px', fontSize: '1.2rem' },
  qrReader: {
    width: '100%',
    maxWidth: '320px',
    margin: '12px auto',
    borderRadius: '8px',
    overflow: 'hidden',
    background: '#000',
  },
  qrReaderHidden: {
    display: 'none',
  },
  form: { display: 'flex', flexDirection: 'column', gap: '10px' },
  input: {
    padding: '10px 14px',
    borderRadius: '8px',
    border: '1px solid rgba(255,255,255,0.15)',
    background: 'rgba(255,255,255,0.06)',
    color: '#fff',
    fontSize: '0.95rem',
    outline: 'none',
  },
  button: {
    width: '100%',
    padding: '10px',
    borderRadius: '8px',
    border: 'none',
    background: '#6c63ff',
    color: '#fff',
    fontSize: '1rem',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'background 0.2s',
  },
  divider: {
    textAlign: 'center',
    margin: '16px 0',
    borderBottom: '1px solid rgba(255,255,255,0.1)',
    lineHeight: '0.1em',
  },
  dividerText: {
    background: '#24243e',
    padding: '0 10px',
    fontSize: '0.8rem',
    color: '#888',
  },
  error: {
    background: 'rgba(255,50,50,0.15)',
    padding: '10px',
    borderRadius: '8px',
    color: '#ff6b6b',
    fontSize: '0.9rem',
    textAlign: 'center',
    marginTop: '12px',
  },
};
